def b64_decode(d): return base64.b64decode(d)
app = Flask(__name__)
@app.route("/")
def home(): return '<a href="/app">APP NOTIF FIX 60%+</a>'
@app.route("/icon.png")
def icon(): return Response(b64_decode(ICON_B64), mimetype="image/png")
@app.route("/app")
def app_route(): return Response(b64_decode(HTML_B64).decode(), mimetype="text/html")
if __name__=="__main__": app.run(host="0.0.0.0", port=int(os.environ.get("PORT",10000)))
